import search from '@jetbrains/icons/search.svg'
import Input, {Size as InputSize} from '@jetbrains/ring-ui-built/components/input/input'
import classNames from 'classnames'
import type * as React from 'react'
import {useCallback, useEffect, useRef, useState} from 'react'

import type {ProjectTreeSearchProps} from './ProjectTreeSearch.types'

import styles from './ProjectTreeSearch.module.css'

const SEARCH_THROTTLE = 200
const LONG_SEARCH_THROTTLE = 500

function ProjectTreeSearch({
  searchQuery = '',
  onChangeQuery,
  onChangeActive,
  onEscape,
  propagateEscape,
  className,
  wrapperClassName,
  selectedItemId,
  inputRef,
  placeholder,
  'aria-label': ariaLabel,
  ...restProps
}: ProjectTreeSearchProps) {
  const [query, setQuery] = useState(searchQuery)
  const inputEl = useRef<HTMLInputElement | null>(null)
  const changeTimeout = useRef<number | null>(null)

  // Equivalent to componentDidMount and componentWillUnmount
  useEffect(() => {
    const onGlobalKeyEvent = (event: KeyboardEvent) => {
      if (event.type === 'keydown' && event.key === 'Escape') {
        inputEl.current?.blur()
        onEscape?.()

        if (event.target === inputEl.current && !propagateEscape) {
          event.stopPropagation()
        }

        onChangeActive?.(false)
        setQuery('')
      }
    }

    document.addEventListener('keydown', onGlobalKeyEvent, true)
    document.addEventListener('keyup', onGlobalKeyEvent, true)

    return () => {
      document.removeEventListener('keydown', onGlobalKeyEvent, true)
      document.removeEventListener('keyup', onGlobalKeyEvent, true)
    }
  }, [onEscape, propagateEscape, onChangeActive])

  const handleChangeQuery = useCallback(
    (newQuery: string) => {
      setQuery(newQuery)
      const cleanedQuery = newQuery.trim()

      if (changeTimeout.current) {
        window.clearTimeout(changeTimeout.current)
      }

      if (!cleanedQuery.length || process.env.NODE_ENV === 'test') {
        onChangeQuery?.(cleanedQuery)
      } else {
        changeTimeout.current = window.setTimeout(
          () => {
            onChangeQuery?.(cleanedQuery)
          },
          cleanedQuery.length > 2 ? SEARCH_THROTTLE : LONG_SEARCH_THROTTLE,
        )
      }
    },
    [onChangeQuery],
  )

  const onChange = useCallback(
    (event: React.SyntheticEvent<HTMLInputElement>) => {
      handleChangeQuery(event.currentTarget.value || '')
    },
    [handleChangeQuery],
  )

  const onClear = useCallback(() => {
    handleChangeQuery('')
    inputEl.current?.blur()
    onChangeActive?.(false)
  }, [handleChangeQuery, onChangeActive])

  const onFocus = useCallback(() => {
    onChangeActive?.(true)
  }, [onChangeActive])

  const onKeyDown = useCallback((event: React.KeyboardEvent<HTMLInputElement>) => {
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowLeft':
        event.stopPropagation()
        return

      case 'Home':
        event.preventDefault()
        event.stopPropagation()
        event.currentTarget.setSelectionRange(
          0,
          event.shiftKey ? event.currentTarget.selectionEnd : 0,
        )
        return

      case 'End':
        event.preventDefault()
        event.stopPropagation()
        const position = event.currentTarget.value.length
        event.currentTarget.setSelectionRange(
          event.shiftKey ? event.currentTarget.selectionStart : position,
          position,
        )
        return

      default:
        return
    }
  }, [])

  const setInputRef = useCallback(
    (el: HTMLInputElement) => {
      if (inputRef) {
        inputRef(el)
      }
      inputEl.current = el
    },
    [inputRef],
  )

  return (
    <div className={wrapperClassName ? wrapperClassName : styles.wrapper}>
      <Input
        autoComplete="off"
        data-test={'project-tree-search'}
        aria-activedescendant={selectedItemId}
        icon={search}
        inputRef={setInputRef}
        className={classNames(styles.search, className)}
        value={query}
        onFocus={onFocus}
        onChange={onChange}
        onClear={onClear}
        onKeyDown={onKeyDown}
        size={InputSize.FULL}
        placeholder={placeholder ?? 'Search by name'}
        aria-label={ariaLabel ?? 'Search by name'}
        {...restProps}
      />
    </div>
  )
}

export default ProjectTreeSearch
