import {matchSidebarItem} from '../../../selectors/projectTrees'
import type {BuildTypeId, PipelineId, ProjectId} from '../../../types'
import type {ProjectsTreeItem, SidebarActiveItem} from '../../../types/projectTrees'
import {cloneActiveItem} from '../../../types/projectTrees'

import {
  FIRST_TITLE_ITEM_HEIGHT,
  NOT_AUTHORIZED_SERVER_ITEM_HEIGHT,
  REGULAR_ITEM_HEIGHT,
  SERVER_ITEM_HEIGHT,
  TITLE_ITEM_HEIGHT,
} from './ProjectsTree.consts'

export const findActiveIndex = (
  item: SidebarActiveItem | null | undefined,
  items: ReadonlyArray<ProjectsTreeItem>,
) => {
  let activeIndex = items.findIndex(matchSidebarItem(item))

  // If there's no item in `favorites`, we should look for it group 'all'.
  // This is because we assume that by default we assume that the item might be in `favorites`,
  // but it's not always the case.
  if (activeIndex === -1 && item != null && item.group === 'favorites') {
    const originalItem = cloneActiveItem(item)

    if (
      originalItem.nodeType === 'bt' ||
      originalItem.nodeType === 'project' ||
      originalItem.nodeType === 'pipeline'
    ) {
      originalItem.group = 'all'
      activeIndex = items.findIndex(matchSidebarItem(originalItem))
    }
  }

  return activeIndex
}

export const isItemNonActionable = (item: ProjectsTreeItem): boolean =>
  (item.itemType === 'title' && item.hasChildren !== true) || item.itemType === 'server'

export function calculateRowHeight(
  index: number,
  items: ReadonlyArray<ProjectsTreeItem | null | undefined>,
) {
  const item: ProjectsTreeItem | null | undefined = items[index]

  // item == null for loader
  if (item == null || item.itemType === 'title') {
    return index === 0 ? FIRST_TITLE_ITEM_HEIGHT : TITLE_ITEM_HEIGHT
  } else if (item.itemType === 'server') {
    return !item.authorized || item.loading ? NOT_AUTHORIZED_SERVER_ITEM_HEIGHT : SERVER_ITEM_HEIGHT
  } else {
    return REGULAR_ITEM_HEIGHT
  }
}

export const calculateRowOffset = (
  index: number,
  items: ReadonlyArray<ProjectsTreeItem | null | undefined>,
): number => items.slice(0, index).reduce((acc, _, i) => acc + calculateRowHeight(i, items), 0)

type IdProps = {
  buildTypeId: BuildTypeId | null | undefined
  projectId: ProjectId | null | undefined
  pipelineId: PipelineId | null | undefined
}

export const getIdProps = (item: ProjectsTreeItem): IdProps => ({
  buildTypeId: item.itemType === 'buildType' || item.itemType === 'template' ? item.id : null,
  projectId: item.itemType === 'project' ? item.id : null,
  pipelineId: item.itemType === 'pipeline' ? item.id : null,
})
