import type {ComponentEnhancer} from 'recompose'
import {branch as branchHOC} from 'recompose'

import compose from 'lodash/flowRight'
import {memo, Suspense} from 'react'

import {withBranchProps} from '../hooks/routes'
import useStatusSubscription from '../hooks/useStatusSubscription'
import type {Branch} from '../services/rest'
import type {ActiveEntityProps, HOC} from '../types'

import withHook from './withHook'
import withWrapper from './withWrapper'

type Props = ActiveEntityProps & {
  branch?: Branch | null
  withoutBranch?: boolean
  blockUpdates?: boolean
  updateOverviewParents?: boolean
}
export default <P extends Props>(timeout?: number): HOC<P, P> =>
  compose(
    memo,
    branchHOC(
      (props: P) => props.branch == null && props.withoutBranch !== true,
      withBranchProps as ComponentEnhancer<Props, Props>,
    ),
    withHook((props: Props) => {
      useStatusSubscription({
        ...props,
        timeout,
      })
    }),
    withWrapper(() => Suspense),
  )
