import Button from '@jetbrains/ring-ui-built/components/button/button'
import {useHref, useLinkClickHandler} from 'react-router'

import {useDarkOrLightTheme} from '../../../hooks/theme/useDarkOrLightTheme'
import {usePermission} from '../../../hooks/usePermission'
import {getCreateProjectHref} from '../../../routes'
import {Permission, ROOT_PROJECT_ID} from '../../../types'
import emptySearchDark from '../../App/SidebarPanel/SidebarPanelContent/SidebarPanelContentNoResults/Emtpy search - dark.svg'
import emptySearchLight from '../../App/SidebarPanel/SidebarPanelContent/SidebarPanelContentNoResults/Emtpy search - light.svg'
import {isCreateProjectNewUiEnabled} from '../../pages/PipelinesPages/utils/featureToggles'

import styles from './ProjectsTree.module.css'

function ProjectsTreePlaceholder() {
  const hasPermissionToCreate = usePermission(Permission.EDIT_PROJECT, ROOT_PROJECT_ID)
  const to = getCreateProjectHref(ROOT_PROJECT_ID)
  const href = useHref(to)
  const onClick = useLinkClickHandler(to)
  const theme = useDarkOrLightTheme()
  return (
    <div className={styles.placeholder}>
      <div className={styles.nothingFoundBox}>
        <img
          alt="Nothing found"
          src={theme === 'dark' ? emptySearchDark : emptySearchLight}
          width={224}
          height={180}
        />
        <div className={styles.message}>{'There is no items with this name'}</div>
        {hasPermissionToCreate &&
          (isCreateProjectNewUiEnabled ? (
            <Button primary href={href} rel="noreferrer" onClick={onClick}>
              {'Create project'}
            </Button>
          ) : (
            <Button primary rel="noreferrer" href={to}>
              {'Create project'}
            </Button>
          ))}
      </div>
    </div>
  )
}

export default ProjectsTreePlaceholder
