import type {LinkProps} from '@jetbrains/ring-ui-built/components/link/link'
import Link from '@jetbrains/ring-ui-built/components/link/link'

import {getClassicOverviewHrefWithCustomBase} from '../routes'
import type {BuildTypeId, FederationServerId, PipelineId, ProjectId} from '../types'

type Props = LinkProps & {
  projectId?: ProjectId | null | undefined
  buildTypeId?: BuildTypeId | null | undefined
  pipelineId?: PipelineId | null | undefined
  serverId: FederationServerId
  isAdmin: boolean
  isTemplate: boolean
}
function ProjectOrBuildTypeExternalLink({
  projectId,
  buildTypeId,
  pipelineId,
  serverId,
  isAdmin,
  isTemplate,
  ...restProps
}: Props) {
  return (
    <Link
      href={getClassicOverviewHrefWithCustomBase({
        projectId,
        buildTypeId,
        pipelineId,
        serverId,
        isAdmin,
        isTemplate,
      })}
      {...restProps}
    />
  )
}
export default ProjectOrBuildTypeExternalLink
