const LEVEL_MARGIN_PX = 16
const MULTISELECT_OFFSET = 10
const MULTISELECT_CHEVRON_OFFSET = 22
const TOOLTIP_OFFSET_LEFT = 20
const TOOLTIP_OFFSET_BOTTOM = 4
const popupDirections = [Directions.TOP_RIGHT]
const CHANGES_COUNTER_LIMIT = internalProps['teamcity.internal.buildChangesPopupLimit']

type StarProps = {
  isStarred: boolean
  starHovered: boolean
  projectId: ProjectId | null | undefined
  onStar: (skipSubprojects?: boolean) => unknown
  onMouseEnter: (arg0: React.MouseEvent | null | undefined) => unknown
  onMouseLeave: (arg0: React.MouseEvent | null | undefined) => unknown
}
const Star = React.memo(function Star({
  isStarred,
  starHovered,
  projectId,
  onStar,
  onMouseEnter,
  onMouseLeave,
}: StarProps) {
  const subprojectsCount = useAppSelector(state => {
    if (projectId == null) {
      return 0
    }

    const overviewData = getOverviewData(state)
    const projects = isStarred ? overviewData : getProjectsData(state)
    return projects.filter(id => getProject(state, id)?.parentProjectId === projectId).length
  })

  const isEdit = React.useContext(EditProjectSidebarContext)
  const star = (
    <FavoriteStar
      isStarred={isStarred}
      showEmpty
      className={styles.iconAction}
      iconWrapperClassName={cn(styles.starIcon, {
        [styles.hovered]: starHovered,
      })}
      onStar={e => {
        if (!isEdit) {
          e?.stopPropagation()
        }

        e?.preventDefault()
        onStar(e?.ctrlKey || e?.metaKey)
      }}
      onMouseEnter={onMouseEnter}
      onMouseLeave={onMouseLeave}
      title={subprojectsCount > 0 ? '' : null}
    />
  )
  const action = isStarred ? 'Remove from favorites' : 'Add to favorites'
  const subprojects = `${subprojectsCount} ${plur('subproject', subprojectsCount)}`

  const getLabel = (withSupbrojects: boolean) =>
    `${action} ${withSupbrojects ? 'with' : 'without'} ${subprojects}`

  return subprojectsCount > 0 ? (
    <Dropdown hoverMode clickMode={false} anchor={star}>
      <PopupMenu
        data={[
          {
            label: getLabel(true),
            description: 'click',
            onClick: () => onStar(false),
          },
          {
            label: getLabel(false),
            description: `${cmdOrCtrl}+click`,
            onClick: () => onStar(true),
          },
        ]}
      />
    </Dropdown>
  ) : (
    star
  )
})
export type MoveParams = {
  projectId: ProjectId | null | undefined
  buildTypeId: BuildTypeId | null | undefined
  shiftBy: number
}
type ItemType =
  | 'buildType'
  | 'pipeline'
  | 'template'
  | 'project'
  | 'title'
  | 'server'
  | 'link'
  | 'action'
  | 'overview'
type BaseProps = {
  id: string
  itemType: ItemType
  href?: string | null | undefined
  icon?: string | null | undefined
  buildTypeId: BuildTypeId | null | undefined
  projectId: ProjectId | null | undefined
  pipelineId: PipelineId | null | undefined
  name: string
  status: BuildStatus | null | undefined
  investigation: $PropertyType<ProjectOrBuildTypeStatusBase, 'investigation'> | null | undefined
  systemProblems: $PropertyType<ProjectOrBuildTypeStatusBase, 'systemProblems'> | null | undefined
  level: number
  collapsible?: boolean
  focusable?: boolean
  expanded?: boolean
  type?: TypeOfBuildType | null | undefined
  selected: boolean
  active: boolean
  searchPattern?: string | null | undefined
  hasOwnPending?: boolean
  pendingCount: number
  runningCount: number
  queuedCount: number
  isFavorites: boolean
  archived?: boolean
  paused?: boolean
  noSettingsAccess?: boolean
  showStarAction?: boolean
  isStarred?: boolean | null | undefined
  authorized?: boolean | null | undefined
  loading?: boolean | null | undefined
  isScrolling?: boolean
  serverId: FederationServerId
  newFailedTestsCountsForRunningBuilds: ReadonlyArray<number> | null | undefined
  newFailedTestsCountForLatestBuild: number
  toggleOverview: (node: ProjectOrBuildTypeNode, on: boolean, skipSubprojects?: boolean) => unknown
  reloadProjects: () => unknown
  editable?: boolean
  isFirstSibling: boolean
  shouldFocus: boolean
  checked: boolean
  indeterminate: boolean
  isDisabled: boolean
  hasReorderedChildren: boolean
  onMove: (arg0: MoveParams) => unknown
  showPathInTitle?: boolean
  showTooltip: boolean
  toggleTooltip: (id: string | null) => void
  isConfigurationPopup?: boolean
  canEditProject?: boolean
  canCreateSubProject?: boolean
  canCreatePipelines?: boolean
}
type Props = BaseProps &
  MeasuredComponentProps & {
    isEdit: boolean
    isPopup: boolean
    isAdmin: boolean
    isMultiselect: boolean
    isAction: boolean
    onClick: () => unknown
    onChevronClick: () => unknown
    onCheck: (arg0: boolean) => unknown
    buildTypeUrlFormat: string | null | undefined
    templateUrlFormat: string | null | undefined
    projectUrlFormat: string | null | undefined
    pipelineUrlFormat: string | null | undefined
  }
type OuterProps = BaseProps & {
  index: number
  onClick: (index: number) => unknown
  onChevronClick: (index: number) => unknown
  onCheck: (arg0: number, arg1: boolean) => unknown
}

const getOffsetForLevel: (level: number) => number = memoize(
  (level: number) => level * LEVEL_MARGIN_PX,
)
type HighlightingCache = WritableKeyValue<string, WritableKeyValue<string, React.ReactNode>>
type GetCustomUrlParams = {
  itemType: ItemType
  buildTypeId: BuildTypeId | null | undefined
  pipelineId: PipelineId | null | undefined
  projectId: ProjectId | null | undefined
  buildTypeUrlFormat: string | null | undefined
  templateUrlFormat: string | null | undefined
  projectUrlFormat: string | null | undefined
  pipelineUrlFormat: string | null | undefined
}
export function getCustomUrl({
  itemType,
  buildTypeId,
  pipelineId,
  projectId,
  buildTypeUrlFormat,
  templateUrlFormat,
  projectUrlFormat,
  pipelineUrlFormat,
}: GetCustomUrlParams): string | null | undefined {
  if (itemType === 'buildType' && buildTypeUrlFormat != null) {
    return buildTypeUrlFormat.replace('{id}', stringifyId(buildTypeId))
  }

  if (itemType === 'pipeline' && pipelineUrlFormat != null) {
    return pipelineUrlFormat.replace('{id}', pipelineId ?? '')
  }

  if (itemType === 'template' && templateUrlFormat != null) {
    return templateUrlFormat.replace('{id}', buildTypeId ?? '')
  }

  if (itemType === 'project' && projectUrlFormat != null) {
    return projectUrlFormat.replace('{id}', stringifyId(projectId))
  }

  return null
}

type ProjectsTreeItemInnerChevronButtonProps = {
  collapsible?: boolean
  expanded?: boolean
  hovered?: boolean
  offsetLeft: number
  isMultiselect?: boolean
  onClick?: (event: React.MouseEvent<any>) => void
  onMouseEnter?: () => void
  onMouseLeave?: () => void
  level?: number
}

function ProjectsTreeItemInnerChevronButton({
  collapsible,
  expanded,
  offsetLeft,
  hovered,
  isMultiselect,
  onClick,
  onMouseEnter,
  onMouseLeave,
  level,
}: ProjectsTreeItemInnerChevronButtonProps) {
  let chevronIcon
  if (level === 0) {
    chevronIcon = expanded ? 'caret-down-12px' : 'caret-right-12px'
  } else {
    chevronIcon = expanded ? 'chevron-down' : 'chevron-right'
  }

  return (
    collapsible && (
      <IconButton
        title={expanded ? 'Collapse' : 'Expand'}
        className={cn(styles.chevronButton, {
          [styles.hovered]: hovered,
        })}
        style={{
          left: offsetLeft + (isMultiselect ? MULTISELECT_CHEVRON_OFFSET : 0),
        }}
        iconClassName={cn(styles.chevronIcon, {
          [styles.topLevel]: level === 0,
        })}
        icon={chevronIcon}
        onClick={onClick}
        onMouseEnter={onMouseEnter}
        onMouseLeave={onMouseLeave}
        data-test={expanded ? 'collapse-button' : 'expand-button'}
        tabIndex={-1}
      />
    )
  )
}

const ProjectsTreeItemInner = React.memo(function ProjectsTreeItemInner({
  shouldFocus,
  toggleOverview,
  itemType,
  projectId,
  buildTypeId,
  pipelineId,
  isStarred,
  reloadProjects,
  serverId,
  onChevronClick,
  onMove,
  id,
  type,
  name,
  icon,
  level,
  selected,
  active,
  searchPattern,
  hasOwnPending,
  pendingCount,
  runningCount,
  queuedCount,
  archived,
  showStarAction,
  isFavorites,
  newFailedTestsCountsForRunningBuilds,
  newFailedTestsCountForLatestBuild,
  isEdit,
  isPopup,
  isConfigurationPopup,
  isAdmin,
  isMultiselect,
  isAction,
  isFirstSibling,
  onClick,
  measureRef,
  contentRect,
  expanded,
  collapsible,
  status,
  investigation,
  paused,
  noSettingsAccess,
  systemProblems,
  href,
  authorized,
  loading,
  editable,
  focusable,
  buildTypeUrlFormat,
  templateUrlFormat,
  projectUrlFormat,
  pipelineUrlFormat,
  checked,
  indeterminate,
  isDisabled,
  onCheck,
  hasReorderedChildren,
  showPathInTitle,
  showTooltip,
  isScrolling,
  toggleTooltip,
  canEditProject,
  canCreateSubProject,
  canCreatePipelines,
}: Props): React.ReactElement | null {
  const dispatch = useAppDispatch()
  const elRef = React.useRef<HTMLDivElement>(null)
  const [starHovered, setStarHovered, unsetStarHovered] = useBoolean(false)
  const [chevronHovered, setChevronHovered, unsetChevronHovered] = useBoolean(false)
  const highlightingCache = React.useRef<HighlightingCache>({})
  const hasFavoriteProjects = useAppSelector(getHasFavoriteProjects) || isConfigurationPopup

  React.useEffect(() => {
    if (shouldFocus && !elRef.current?.contains(document.activeElement)) {
      elRef.current?.parentElement?.querySelector<HTMLElement>('[data-sidebar-focusable]')?.focus()
    }
  }, [shouldFocus])

  const onStarClick = React.useCallback(
    (skipSubprojects?: boolean) => {
      let node: ProjectOrBuildTypeNode | null | undefined

      if (itemType === 'project' && projectId != null) {
        node = {
          nodeType: 'project',
          id: projectId,
        }
      } else if (itemType === 'buildType' && buildTypeId != null) {
        node = {
          nodeType: 'bt',
          id: buildTypeId,
        }
      }

      if (node) {
        toggleOverview(node, !isStarred, skipSubprojects)
      }
    },
    [toggleOverview, itemType, projectId, buildTypeId, isStarred],
  )
  const onReloadProjectsButtonClick = React.useCallback(
    (event: React.MouseEvent<any>) => {
      event.stopPropagation()
      event.preventDefault()
      reloadProjects()
    },
    [reloadProjects],
  )
  const handleChevronClick = React.useCallback(
    (event: React.MouseEvent<any>) => {
      event.stopPropagation()
      event.preventDefault()
      onChevronClick()
    },
    [onChevronClick],
  )
  const handleMove = React.useCallback(
    () =>
      onMove({
        projectId,
        buildTypeId,
        shiftBy: -1,
      }),
    [projectId, buildTypeId, onMove],
  )

  const renderNameWithHighlighting = useCallback(() => {
    if (searchPattern == null) {
      return name
    }

    const cached = highlightingCache.current[name]?.[searchPattern]

    if (cached != null) {
      return cached
    }

    let output: React.ReactNode
    const query = new RegExp(searchPattern, 'igm')

    if (query.test(name)) {
      const tempArr: React.ReactNode[] = []
      name.split(query).forEach((str, index) => {
        if (str) {
          tempArr.push(
            <span
              key={index} /* eslint-disable-line react/no-array-index-key */
              className={
                new RegExp(searchPattern, 'igm').test(str) ? styles.highlighting : undefined
              }
            >
              {str}
            </span>,
          )
        }
      })
      output = tempArr
    } else {
      output = name
    }

    let cache = highlightingCache.current[name]

    if (cache == null) {
      cache = highlightingCache.current[name] = {}
    }

    cache[searchPattern] = output
    return output
  }, [name, searchPattern])

  const offsetLeft = getOffsetForLevel(level) + (isMultiselect ? MULTISELECT_OFFSET : 0)
  const chevronOffset =
    getOffsetForLevel(level + (!hasFavoriteProjects && isEmpty(searchPattern) ? -1 : 0)) +
    (isMultiselect ? MULTISELECT_OFFSET : 0)

  const renderStatusIcon = useCallback(() => {
    if (!isValue(EntityIconType, itemType)) {
      return null
    }

    let iconStatus: 'failed' | 'successful' | null | undefined
    let title
    let iconItemType = itemType

    if (!isEdit && !archived && !isAdmin) {
      switch (status) {
        case 'SUCCESS':
        case 'WARNING':
          iconStatus = 'successful'
          break

        case 'FAILURE':
        case 'ERROR':
          iconStatus = 'failed'
          break

        default:
          iconStatus = null
          break
      }

      if (paused === true) {
        title = 'Build configuration was paused'
      } else if (investigation === InvestigationStates.TAKEN) {
        title = 'Investigation is assigned'
        iconItemType = EntityIconType.INVESTIGATION
      }
    }

    return (
      <ProjectOrBuildTypeIcon
        title={title}
        type={iconItemType}
        paused={paused}
        composite={type === 'composite'}
        status={iconStatus}
        size="M"
        locked={isAdmin && noSettingsAccess}
      />
    )
  }, [archived, investigation, isAdmin, isEdit, itemType, noSettingsAccess, paused, status, type])

  const commonClassNames = cn(styles.projectsTreeItem, {
    [styles.selected]: selected,
    [styles.active]: active,
    [styles.archived]: archived,
    [styles.action]: itemType === 'action' || isAction,
    [styles.checkbox]: isMultiselect,
    [styles.disabled]: isDisabled,
  })
  const commonProps = {
    id,
    onClick,
    'data-sidebar-focusable': 'true',
    className: commonClassNames,
  }

  const isComposite = type === 'composite'
  const isExternalLink = isPopup || serverId !== baseUri
  const path = useAppSelector(state =>
    showPathInTitle && itemType === 'project'
      ? getFullPath(state, getProjectBuildTypeFilter({projectId}))
          .map(item => item.name)
          .join(' / ')
      : null,
  )
  const shouldShowNameTooltip =
    (path != null && path.length > 0) ||
    (contentRect.scroll?.width ?? 0) > (contentRect.client?.width ?? 0)
  const children = useMemo(
    () => (
      <div
        className={cn(styles.content, {[styles.offset]: isMultiselect})}
        data-test="sidebar-item"
        data-favorite={isFavorites}
        data-project-id={projectId}
        data-buildtype-id={buildTypeId}
        data-selected={selected}
      >
        <span
          className={styles.elementWithChevron}
          style={{
            paddingLeft: getOffsetForLevel(
              level + (hasFavoriteProjects || !isEmpty(searchPattern) ? 1 : 0),
            ),
          }}
        />
        <span>
          {icon != null ? (
            <span>
              <SvgIcon className={styles.linkIcon} icon={icon} title={name} />
            </span>
          ) : (
            renderStatusIcon()
          )}
        </span>
        <span
          className={styles.name}
          ref={measureRef}
          aria-label={name}
          onMouseEnter={shouldShowNameTooltip ? () => toggleTooltip(id) : undefined}
          onMouseLeave={shouldShowNameTooltip ? () => toggleTooltip(null) : undefined}
        >
          {renderNameWithHighlighting()}
        </span>
        {!isEdit && !isAdmin ? (
          <>
            {pendingCount > 0 && !isHideProjectTreeNumbersEnabled ? (
              <Tooltip
                className={cn(styles.pendingCounter, {
                  [styles.withOwnPending]: hasOwnPending,
                })}
                title={`${pendingCount} pending change${pendingCount > 1 ? 's' : ''} in default branch`}
                delay={TOOLTIP_TIMEOUT_MS}
                long
              >
                {pendingCount <= CHANGES_COUNTER_LIMIT
                  ? ` +${pendingCount}`
                  : ` ${CHANGES_COUNTER_LIMIT}+`}
              </Tooltip>
            ) : null}
            {!isComposite &&
            newFailedTestsCountsForRunningBuilds?.length &&
            !isHideProjectTreeNumbersEnabled ? (
              <Tooltip
                className={styles.newFailedTestsCounter}
                title={`${newFailedTestsCountsForRunningBuilds[0]} new failed test${
                  newFailedTestsCountsForRunningBuilds[0] > 1 ? 's' : ''
                } in the last running build in default branch`}
                delay={TOOLTIP_TIMEOUT_MS}
                long
              >
                {` ↓${newFailedTestsCountsForRunningBuilds[0]}`}
              </Tooltip>
            ) : null}
            {!isComposite &&
            newFailedTestsCountForLatestBuild > 0 &&
            !isHideProjectTreeNumbersEnabled &&
            !newFailedTestsCountsForRunningBuilds ? (
              <Tooltip
                className={styles.newFailedTestsCounter}
                title={`${newFailedTestsCountForLatestBuild} new failed test${
                  newFailedTestsCountForLatestBuild > 1 ? 's' : ''
                } in the last build in default branch`}
                delay={TOOLTIP_TIMEOUT_MS}
                long
              >
                {` ↓${newFailedTestsCountForLatestBuild}`}
              </Tooltip>
            ) : null}
            {runningCount > 0 ? (
              <Tooltip
                className={styles.counter}
                title={`${runningCount} running build${runningCount > 1 ? 's' : ''}`}
                delay={TOOLTIP_TIMEOUT_MS}
                long
              >
                <SvgIcon icon="spinner-static" className={styles.counterIcon} />
                <span className={styles.counterText}>{runningCount}</span>
              </Tooltip>
            ) : null}
            {queuedCount > 0 ? (
              <Tooltip
                className={styles.counter}
                title={`${queuedCount} queued build${queuedCount > 1 ? 's' : ''}`}
                delay={TOOLTIP_TIMEOUT_MS}
                long
              >
                <SvgIcon icon="hourglass" className={styles.counterIcon} />
                <span className={styles.counterText}>{queuedCount}</span>
              </Tooltip>
            ) : null}
            {systemProblems != null && systemProblems.length > 0 && (
              <Tooltip title={systemProblems[0].title} delay={TOOLTIP_TIMEOUT_MS} long>
                <SvgIcon icon="warning" className={styles.warningIcon} />
              </Tooltip>
            )}
          </>
        ) : null}
        {projectId != null && hasReorderedChildren && (
          <Button
            inline
            className={styles.reordered}
            onClick={() => dispatch(resetOrderInProject(projectId))}
          >
            {'Reset order'}
          </Button>
        )}
        {isEdit && isFavorites && (
          <IconButton
            disabled={isFirstSibling}
            className={styles.iconAction}
            icon="arrow-up"
            title="Move up"
            onClick={handleMove}
          />
        )}
        {archived !== true && (showStarAction === true || isEdit) && !isExternalLink ? (
          <Star
            projectId={projectId}
            isStarred={Boolean(isStarred)}
            starHovered={starHovered}
            onStar={onStarClick}
            onMouseEnter={setStarHovered}
            onMouseLeave={unsetStarHovered}
          />
        ) : null}
        {projectId != null && !archived && !isEdit && (canEditProject || canCreateSubProject) && (
          <ProjectsTreeItemCreateButton
            projectId={projectId}
            canEditProject={canEditProject}
            canCreateSubProject={canCreateSubProject}
            canCreatePipelines={canCreatePipelines}
          />
        )}
        {archived === true && <span className={styles.note}>{'Archived'}</span>}
      </div>
    ),
    [
      isMultiselect,
      isFavorites,
      projectId,
      buildTypeId,
      selected,
      level,
      hasFavoriteProjects,
      searchPattern,
      icon,
      name,
      renderStatusIcon,
      measureRef,
      shouldShowNameTooltip,
      renderNameWithHighlighting,
      isEdit,
      isAdmin,
      pendingCount,
      hasOwnPending,
      isComposite,
      newFailedTestsCountsForRunningBuilds,
      newFailedTestsCountForLatestBuild,
      runningCount,
      queuedCount,
      systemProblems,
      hasReorderedChildren,
      isFirstSibling,
      handleMove,
      archived,
      showStarAction,
      isExternalLink,
      isStarred,
      starHovered,
      onStarClick,
      setStarHovered,
      unsetStarHovered,
      canEditProject,
      canCreateSubProject,
      canCreatePipelines,
      toggleTooltip,
      id,
      dispatch,
    ],
  )
  function renderItem() {
    if (isMultiselect) {
      return (
        <Checkbox
          {...commonProps}
          containerClassName={commonProps.className}
          className=""
          labelClassName={styles.checkboxLabel}
          checked={checked}
          indeterminate={indeterminate}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => onCheck(e.currentTarget.checked)}
          onClick={noop}
          disabled={isDisabled}
        >
          {children}
        </Checkbox>
      )
    }

    if (isEdit || isAction || itemType === 'action') {
      return (
        <div
          {...commonProps}
          role="button"
          tabIndex={0} // key events are handled on tree level
          onKeyDown={noop}
        >
          {children}
        </div>
      )
    }

    const customUrl = getCustomUrl({
      itemType,
      buildTypeId,
      pipelineId,
      projectId,
      buildTypeUrlFormat,
      templateUrlFormat,
      projectUrlFormat,
      pipelineUrlFormat,
    })

    if (customUrl != null) {
      return (
        <RouterLinkWrapper toAdminPage={isAdmin}>
          <Link
            {...commonProps}
            href={customUrl}
            onKeyDown={e => {
              if (e.key === 'Enter') {
                window.location.href = customUrl
              }
            }}
          >
            {children}
          </Link>
        </RouterLinkWrapper>
      )
    }

    const linkProps = {
      ...commonProps,
      buildTypeId,
      projectId,
      pipelineId,
      target: isExternalLink && !isPopup ? '_blank' : '_self',
      rel: 'noreferrer',
      children,
    }

    return isExternalLink ? (
      <ProjectOrBuildTypeExternalLink
        {...linkProps}
        serverId={serverId}
        isAdmin={isAdmin}
        isTemplate={itemType === 'template'}
      />
    ) : (
      <EntityLink {...linkProps} isAllProjects={!isFavorites && isStarred !== true} />
    )
  }

  function renderLink() {
    const content = (
      <div className={cn(styles.content, {[styles.offset]: isMultiselect})}>
        <span className={styles.elementWithoutChevron} />
        {icon != null ? (
          <span>
            <SvgIcon className={styles.linkIcon} icon={icon} title={name} />
          </span>
        ) : null}
        <span>{name}</span>
        {isAdmin ? (
          <span>
            <SvgIcon className={styles.newWindowLinkIcon} icon="new-window" title={name} />
          </span>
        ) : null}
      </div>
    )

    if (href == null) {
      return null
    }

    if (isAdmin) {
      return (
        <Link {...commonProps} href={href} target={'_blank'} rel={'noreferrer'}>
          {content}
        </Link>
      )
    }
    return (
      <RouterLink {...commonProps} to={href}>
        {content}
      </RouterLink>
    )
  }

  function renderTooltip() {
    return (
      <ThemeProvider theme={Theme.DARK} passToPopups>
        <Popup
          className={cn(styles.tooltip, {
            [styles.inPopup]: isPopup || isEdit,
          })}
          left={offsetLeft + TOOLTIP_OFFSET_LEFT}
          directions={popupDirections}
          offset={TOOLTIP_OFFSET_BOTTOM}
        >
          <div>{path || name}</div>
        </Popup>
      </ThemeProvider>
    )
  }

  if (itemType === 'title') {
    const projectWithNoFavorites = name === 'PROJECTS' && !hasFavoriteProjects
    const titleClassName = cn(
      styles.title,
      !collapsible || projectWithNoFavorites ? styles.titleWithoutChevron : '',
    )

    const titleProps =
      focusable === true
        ? {
            className: titleClassName,
          }
        : {
            className: titleClassName,
            'data-hint-container-id': isFavorites ? favoritesHint.id : null,
          }
    return (
      <>
        <ProjectsTreeItemInnerChevronButton
          collapsible={projectWithNoFavorites ? false : collapsible}
          expanded={expanded}
          hovered={chevronHovered}
          onClick={handleChevronClick}
          onMouseEnter={setChevronHovered}
          onMouseLeave={unsetChevronHovered}
          offsetLeft={chevronOffset}
          isMultiselect={isMultiselect}
          level={level}
        />
        <div id={id} ref={elRef} {...titleProps} data-test="ring-title">
          {collapsible && !projectWithNoFavorites && <span className={styles.titleChevron} />}
          <span
            onClick={projectWithNoFavorites ? () => {} : handleChevronClick}
            onKeyDown={_ => {}}
            role="button"
            tabIndex={0}
            className={cn(styles.name, {[styles.bold]: level === 0})}
          >
            {name}
          </span>
          {((editable === true && !isEdit) || projectWithNoFavorites) && <EditProjectSidebar />}
        </div>
      </>
    )
  }

  if (itemType === 'server') {
    return (
      <div className={styles.server}>
        <label title={name} className={styles.serverTitle}>
          {name}
        </label>
        <div className={styles.serverDetails}>
          {loading !== true && authorized !== true ? (
            <>
              <label>{'Need to '}</label>
              <Link target="_blank" rel="noreferrer" href={name}>
                {'log in…'}
              </Link>
              <label>{' or '}</label>
              <Button
                className={styles.updateButton}
                onClick={onReloadProjectsButtonClick}
                data-inside-sidebar
                inline
              >
                {'update data'}
              </Button>
            </>
          ) : null}
          {loading === true ? <LoaderInline>{'Projects are loading…'}</LoaderInline> : null}
        </div>
      </div>
    )
  }

  if (itemType === 'link') {
    return renderLink()
  }

  if (isScrolling) {
    return (
      <div>
        <ProjectsTreeItemInnerChevronButton
          collapsible={collapsible}
          expanded={expanded}
          offsetLeft={chevronOffset}
          isMultiselect={isMultiselect}
        />
        {renderItem()}
      </div>
    )
  }

  const item = (
    <div>
      <ProjectsTreeItemInnerChevronButton
        collapsible={collapsible}
        expanded={expanded}
        hovered={chevronHovered}
        onClick={handleChevronClick}
        onMouseEnter={setChevronHovered}
        onMouseLeave={unsetChevronHovered}
        offsetLeft={chevronOffset}
        isMultiselect={isMultiselect}
      />
      {renderItem()}
    </div>
  )
  return (
    <div ref={elRef} data-test-itemtype={itemType}>
      {projectId !== ROOT_PROJECT_ID && !isEdit && !archived && (
        <StatusUpdater
          projectId={projectId}
          buildTypeId={buildTypeId}
          pipelineId={pipelineId}
          subscribeDelayMS={1000}
          updateOverviewParents
          withoutBranch
        />
      )}
      {showTooltip && renderTooltip()}
      {item}
    </div>
  )
})
const ProjectsTreeItem: React.ComponentType<OuterProps> = compose(
  React.memo,
  withContentRect(['scroll', 'client']),
)(function ProjectsTreeItem({
  index,
  onClick,
  onChevronClick,
  onCheck,
  isConfigurationPopup,
  ...restProps
}: OuterProps & MeasuredComponentProps) {
  const {
    isPopup,
    isAdmin,
    isMultiselect = false,
    isAction = false,
    buildTypeUrlFormat,
    templateUrlFormat,
    projectUrlFormat,
    pipelineUrlFormat,
  } = React.useContext(ProjectsTreeContext)
  return (
    <ProjectsTreeItemInner
      {...restProps}
      isEdit={React.useContext(EditProjectSidebarContext)}
      isPopup={isPopup}
      isConfigurationPopup={isConfigurationPopup}
      isAdmin={isAdmin}
      isMultiselect={isMultiselect}
      isAction={isAction}
      onClick={useEventCallback(() => onClick(index))}
      onChevronClick={useEventCallback(() => onChevronClick(index))}
      onCheck={useEventCallback(checked => onCheck(index, checked))}
      buildTypeUrlFormat={buildTypeUrlFormat}
      templateUrlFormat={templateUrlFormat}
      projectUrlFormat={projectUrlFormat}
      pipelineUrlFormat={pipelineUrlFormat}
    />
  )
})
export default ProjectsTreeItem
type StyledProps = OuterProps & {
  style: KeyValue<string, string | number>
}

function StyledProjectsTreeItemComponent(props: StyledProps) {
  useHint(props.isFavorites && props.itemType === 'title' ? favoritesHint : null)
  const {style, ...restProps} = props
  return (
    <div style={style} role="row" className={styles.row}>
      <div role="gridcell" aria-selected={restProps.selected} className={styles.gridcell}>
        <ProjectsTreeItem {...restProps} />
      </div>
    </div>
  )
}

export const StyledProjectsTreeItem = React.memo(StyledProjectsTreeItemComponent)
