import getUID from '@jetbrains/ring-ui-built/components/global/get-uid'
import memoize from '@jetbrains/ring-ui-built/components/global/memoize'
import Loader from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import Shortcuts from '@jetbrains/ring-ui-built/components/shortcuts/shortcuts'
import {PlaceId} from '@jetbrains/teamcity-ui/dist/plugin'
import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import * as React from 'react'
import {Suspense} from 'react'
import AutoSizer from 'react-virtualized/dist/es/AutoSizer'
import type {ScrollParams} from 'react-virtualized/dist/es/Grid'
import type {ListProps} from 'react-virtualized/dist/es/List'
import List from 'react-virtualized/dist/es/List'

import {getStatusKey} from '../../../rest/schemata'
import {actions, matchSidebarItem} from '../../../selectors/projectTrees'
import type {ProjectOrBuildTypeStatus} from '../../../types'
import {ALL_PROJECTS_TITLE_ID, ROOT_PROJECT_ID} from '../../../types'
import type {ProjectsTreeItem} from '../../../types/projectTrees'
import {
  getNodeFromItem,
  getProjectTreeItemId,
  getProjectTreeItemStatusRequest,
} from '../../../types/projectTrees'
import {noop} from '../../../utils/empty'
import SidebarSkeleton from '../../App/SidebarPanel/SidebarPanelContent/SidebarSkeleton/SidebarSkeleton'
import Plugin from '../Plugin/Plugin'
import {TreeEventType} from '../Sidebar/Sidebar.types'
import {keyboardToEditTreeEvent, keyboardToTreeEvent} from '../Sidebar/Sidebar.utils'

import {REGULAR_ITEM_HEIGHT, TITLE_ITEM_HEIGHT, TOOLTIP_TIMEOUT_MS} from './ProjectsTree.consts'
import ProjectsTreePlaceholder from './ProjectsTree.placeholder'
import type {DefaultProps, Props, State} from './ProjectsTree.types'
import {
  calculateRowHeight,
  calculateRowOffset,
  findActiveIndex,
  getIdProps,
  isItemNonActionable,
} from './ProjectsTree.utils'
import type {MoveParams} from './ProjectsTreeItem/ProjectsTreeItem'
import {StyledProjectsTreeItem} from './ProjectsTreeItem/ProjectsTreeItem'

import styles from './ProjectsTree.module.css'

const containerProps = {
  'data-sidebar-list': true,
}
const ProjectsTreeList = React.forwardRef<List, ListProps>(function ProjectsTreeList(props, ref) {
  return (
    <AutoSizer>
      {React.useCallback(
        ({width, height}) => (
          <List
            {...(props as ListProps)}
            ref={ref}
            width={width}
            height={height}
            containerRole="none" // row role is set by rowRenderer
          />
        ),
        [props, ref],
      )}
    </AutoSizer>
  )
})
type ShortcutsMap = {
  left: (e: Event) => void
}

class ProjectsTree extends React.Component<Props, State> {
  static defaultProps: DefaultProps = {
    collapsed: false,
    isEdit: false,
    isPopup: false,
    userCanEdit: false,
    projectsSelectable: true,
    ready: false,
    allProjectsReady: true,
    searchQuery: '',
    reloadProjects: noop,
    onSelect: noop,
    onScroll: noop,
    onCheck: noop,
    renderSearch: () => null,
    toggleExpandAll: noop,
  }

  static getDerivedStateFromProps(
    {searchActive, searchQuery, items, activeItem, isPopup, projectsSelectable}: Readonly<Props>,
    {
      prevSearchActive,
      prevSearchQuery,
      prevActiveItem,
      prevSelectedIndex,
      prevSelectedItem,
      selected,
      shouldScrollToSelected,
    }: State,
  ): Partial<State> {
    const activeIndex = findActiveIndex(activeItem, items)
    let selectedIndex = selected === -1 ? activeIndex : selected
    let selectedItem = items[selectedIndex]
    const commonState = {
      prevSearchActive: searchActive,
      prevSearchQuery: searchQuery,
      prevActiveIndex: activeIndex,
      prevActiveItem: activeItem,
    }
    const activeItemChanged = activeIndex !== -1 && activeItem !== prevActiveItem

    if (
      searchActive === true &&
      (prevSearchActive !== true || searchQuery !== prevSearchQuery) &&
      !(isPopup && activeItemChanged)
    ) {
      // select first match after opening search or changing query
      selectedIndex = items.findIndex(
        item => item.isFullMatch === true && (projectsSelectable || item.itemType !== 'project'),
      )

      /*
       * Case: It's the first open tree without any searching coincidences
       * Result: Selected should be the first item
       */
      if (isPopup && selectedIndex === -1 && activeIndex === -1) {
        selectedIndex = items.findIndex(item => projectsSelectable || item.itemType !== 'project')
      }
    } else if (activeItemChanged || (prevSearchActive && !searchActive)) {
      // select active item on navigation
      selectedIndex = activeIndex
    } else if (
      selectedIndex === prevSelectedIndex &&
      prevSelectedItem &&
      selectedItem &&
      selectedItem.id !== prevSelectedItem.id
    ) {
      // Preserve selection when the beginning of the list has changed
      const newSelectedIndex = items.findIndex(item => {
        if (item.id === prevSelectedItem.id && item.itemType === prevSelectedItem.itemType) {
          if (item.itemType === 'project' || item.itemType === 'buildType') {
            return item.group === prevSelectedItem.group
          }

          if (item.itemType === 'title') {
            return item.name === prevSelectedItem.name
          }

          return true
        }

        return false
      })

      if (newSelectedIndex >= 0) {
        selectedIndex = newSelectedIndex
      }
    }

    selectedItem = items[selectedIndex]

    if (selectedItem != null && prevSelectedIndex != null && isItemNonActionable(selectedItem)) {
      selectedIndex += selectedIndex > prevSelectedIndex ? 1 : -1

      if (selectedIndex < 0 || selectedIndex > items.length - 1) {
        selectedIndex = prevSelectedIndex
      }
    }

    return {
      ...commonState,
      selected: selectedIndex,
      prevSelectedIndex: selectedIndex,
      prevSelectedItem: items[selectedIndex],
      shouldScrollToSelected: selectedIndex !== selected ? true : shouldScrollToSelected,
    }
  }

  scrollBarWidth: number | null | undefined = null
  list: List | null | undefined = null
  tree: HTMLElement | null | undefined = null
  search: HTMLInputElement | null | undefined = null
  sidebarRef: {
    current: null | HTMLDivElement
  } = React.createRef<any>()

  shortcutsScope: string = getUID('projects-tree-')
  shortcutsMap: ShortcutsMap = {
    left: e => {
      if (
        e.target instanceof HTMLElement &&
        (e.target.dataset.mainRouter || e.target.dataset.mainPanel)
      ) {
        this.setState({
          shouldFocusSelected: true,
          shouldScrollToSelected: true,
        })
      }
    },
  }

  hoverTimeout?: number | null

  pageStartIndex = -1
  pageEndIndex = -1
  blurTO: number | null | undefined
  getSearchPattern: (query: string) => string | null | undefined = memoize((query: string) => {
    if (!query) {
      return null
    }

    const rt = query.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&').trim()

    if (!rt) {
      return null
    }

    return `(${rt.replace(/ +/g, ' ').replace(/\s/g, ')|(')})`
  })

  state: State = {
    selected: -1,
    shouldFocusSelected: false,
    shouldScrollToSelected: false,
    showTooltipFor: null,
  }

  focusList: () => void = () => {
    this.tree?.querySelector<HTMLElement>('[data-sidebar-list]')?.focus()
  }

  setListRef: (arg0: List | null | undefined) => void = el => {
    this.list = el
  }

  setTreeRef: (arg0: HTMLElement | null | undefined) => void = el => {
    this.tree = el
  }

  setSearchRef: (arg0: HTMLInputElement | null | undefined) => void = el => {
    this.search = el
  }

  rowRenderer: (arg0: {
    index: number
    isScrolling: boolean
    style: KeyValue<string, string | number>
  }) => React.ReactNode = ({
    index,
    style,
    isScrolling,
  }: {
    index: number
    isScrolling: boolean
    style: KeyValue<string, string | number>
  }): React.ReactNode => {
    const {
      items,
      statuses,
      searchQuery,
      toggleOverview,
      reloadProjects,
      userCanEdit,
      checkedItems = [],
      isPopup,
    } = this.props
    const {selected, prevActiveIndex = -1, shouldFocusSelected}: State = this.state
    const item: ProjectsTreeItem | null | undefined = items[index]

    if (item == null) {
      return (
        <div role="row" className={styles.loader} style={style} key={`loader_${index}`}>
          <Loader />
          <span role="cell" className={styles.loaderText}>
            {' '}
            {'Projects are loading...'}
          </span>
        </div>
      )
    }

    const statusRequest = getProjectTreeItemStatusRequest(item)
    const statusKey = statusRequest ? getStatusKey(statusRequest) : null
    const statusInfo: ProjectOrBuildTypeStatus | null | undefined =
      statuses && statusKey ? statuses[statusKey] : null
    const {canCreateSubProject, canEditProject, canCreatePipelines} =
      (statusInfo != null && 'projectPermissions' in statusInfo && statusInfo.projectPermissions) ||
      {}
    const id = getProjectTreeItemId(item)
    const checkedItem = checkedItems.length
      ? checkedItems.find(({node}) => matchSidebarItem(node)(item))
      : null
    const isActive = item === items[prevActiveIndex]

    return (
      <StyledProjectsTreeItem
        isFavorites={item.group === 'favorites'}
        id={id}
        key={id}
        {...getIdProps(item)}
        authorized={item.itemType === 'server' ? item.authorized : null}
        loading={item.itemType === 'server' ? item.loading : null}
        serverId={item.serverId}
        style={style}
        isScrolling={isScrolling}
        itemType={item.itemType}
        href={item.itemType === 'link' ? item.href : null}
        icon={item.icon}
        name={item.name}
        collapsible={item.hasChildren}
        expanded={item.expanded}
        focusable={item.focusable}
        level={item.level}
        type={item.type}
        archived={item.archived}
        paused={item.paused}
        noSettingsAccess={item.noSettingsAccess}
        selected={selected === index}
        shouldFocus={!isScrolling && selected === index && shouldFocusSelected}
        active={isActive}
        onClick={this.onItemClick}
        onChevronClick={this.onItemChevronClick}
        index={index}
        searchPattern={this.getSearchPattern(searchQuery)}
        status={statusInfo?.status}
        investigation={statusInfo?.investigation}
        systemProblems={statusInfo?.systemProblems}
        hasOwnPending={statusInfo?.hasOwnPending}
        pendingCount={statusInfo?.pending ?? 0}
        runningCount={statusInfo?.running ?? 0}
        queuedCount={statusInfo?.queued ?? 0}
        showStarAction={false} // don't show stars during the search
        isStarred={item.isStarred === true}
        editable={userCanEdit && item.editable}
        newFailedTestsCountsForRunningBuilds={statusInfo?.failedCounts?.inRunning}
        newFailedTestsCountForLatestBuild={statusInfo?.failedCounts?.inLatestFinished ?? 0}
        toggleOverview={toggleOverview ?? noop}
        reloadProjects={reloadProjects}
        isFirstSibling={
          item ===
          items.find(
            otherItem =>
              otherItem.group === item.group &&
              otherItem.itemType === item.itemType &&
              otherItem.parentId === item.parentId,
          )
        }
        onMove={this.handleMove}
        checked={checkedItem?.state === 'CHECKED'}
        indeterminate={checkedItem?.state === 'INDETERMINATE'}
        onCheck={this.onItemCheck}
        isDisabled={item.isDisabled === true}
        hasReorderedChildren={item.hasReorderedChildren === true}
        showPathInTitle={
          item.parentId === ROOT_PROJECT_ID && item.actualParentId !== ROOT_PROJECT_ID
        }
        showTooltip={this.state.showTooltipFor === id}
        toggleTooltip={this.toggleTooltip}
        isConfigurationPopup={isPopup}
        canEditProject={canEditProject}
        canCreateSubProject={canCreateSubProject}
        canCreatePipelines={canCreatePipelines}
      />
    )
  }

  onKeyDown: (event: React.KeyboardEvent<EventTarget>) => void = event => {
    // Do nothing if create entity button is clicked
    if (event.target instanceof Element && event.target.hasAttribute('data-create-entity-button')) {
      return
    }

    const {
      toggleExpandState,
      toggleExpandAll,
      items,
      isEdit,
      changeActiveItem,
      onSelect,
      dispatch,
      toggleOverview,
    } = this.props
    const {selected} = this.state
    const itemsCount = items.length

    if (itemsCount === 0) {
      return
    }

    // Make sure that the focus is on the sidebar, which is not the case,
    // if the event is received from a link in the popup, which is physically outside.
    if (event.target instanceof Node && !this.sidebarRef.current?.contains(event.target)) {
      this.focusList()
    }

    // Checkbox toggle
    if (event.target instanceof HTMLInputElement && event.key === ' ') {
      return
    }

    // Typing a character, shift is OK
    if (
      event.key === 'Backspace' ||
      (event.key.length === 1 && !event.ctrlKey && !event.metaKey && !event.altKey)
    ) {
      this.focusQueryIfSearchIsActive()
      return
    }

    if (
      event.key === 'Enter' &&
      !isEdit &&
      onSelect === noop &&
      event.target instanceof Node &&
      this.tree?.contains(event.target)
    ) {
      return
    }

    const treeEvent =
      (isEdit && keyboardToEditTreeEvent(event, items, selected)) ||
      keyboardToTreeEvent(
        event,
        items,
        selected > -1 ? selected : this.pageStartIndex,
        this.pageStartIndex,
        this.pageEndIndex,
      )

    if (treeEvent == null) {
      return
    }

    if (treeEvent.type === TreeEventType.EVENT_TYPE_FOCUS) {
      if (treeEvent.index < 0) {
        this.focusQueryIfSearchIsActive()
      } else if (treeEvent.index < items.length) {
        this.select(() => treeEvent.index)
      }
    }

    if (treeEvent.type === TreeEventType.EVENT_TYPE_MOVE_UP) {
      this.moveSelectedItem(-1)
    }

    if (treeEvent.type === TreeEventType.EVENT_TYPE_MOVE_DOWN) {
      this.moveSelectedItem(1)
    }

    const item = items[treeEvent.index]

    if (treeEvent.type === TreeEventType.EVENT_TYPE_EXPAND) {
      if (item.id === ALL_PROJECTS_TITLE_ID) {
        toggleExpandAll(true)
      } else if (item.itemType === 'project') {
        toggleExpandState(item.id, true, item.group)
      }
    }

    if (treeEvent.type === TreeEventType.EVENT_TYPE_COLLAPSE) {
      if (item.id === ALL_PROJECTS_TITLE_ID) {
        toggleExpandAll(false)
      } else if (item.itemType === 'project') {
        toggleExpandState(item.id, false, item.group)
      }
    }

    if (treeEvent.type === TreeEventType.EVENT_TYPE_SELECT) {
      if (item.itemType !== 'title' && changeActiveItem != null) {
        event.preventDefault()
        changeActiveItem(item)
      }

      if (isEdit) {
        const node = getNodeFromItem(item)

        if (node != null && toggleOverview != null) {
          toggleOverview(node, !item.isStarred, event.ctrlKey || event.metaKey)
        }
      }

      if (item.itemType === 'action') {
        dispatch(typeof item.action === 'string' ? actions[item.action]() : item.action())
      }

      onSelect(item)
    }
  }

  onItemClick: (arg0: number) => void = index => {
    this.select(() => index)
    const {items, dispatch, onSelect} = this.props
    const item = items[index]
    onSelect(item)

    if (item.itemType === 'action') {
      dispatch(typeof item.action === 'string' ? actions[item.action]() : item.action())
    }
  }

  onItemCheck: (arg0: number, arg1: boolean) => void = (index, checked) => {
    const {items, onCheck} = this.props
    const item = items[index]
    onCheck(item, checked)
  }

  onItemChevronClick: (arg0: number) => void = index => {
    const {items, toggleExpandState, toggleExpandAll}: Props = this.props
    this.select(() => index)
    const item: ProjectsTreeItem = items[index]

    switch (item.itemType) {
      case 'title':
        toggleExpandAll(!item.expanded)
        break

      case 'project':
        toggleExpandState(item.id, !item.expanded, item.group)
        break

      default:
    }
  }

  onTreeBlur: (arg0: React.FocusEvent) => void = e => {
    if (e.relatedTarget instanceof Node && !this.tree?.contains(e.relatedTarget)) {
      this.blurTO = window.setTimeout(
        () =>
          this.setState({
            shouldFocusSelected: false,
            shouldScrollToSelected: false,
          }),
        0,
      )
    }
  }

  onTreeFocus: () => void = () => {
    if (this.blurTO != null) {
      window.clearTimeout(this.blurTO)
      this.blurTO = null
    }
  }

  onListScroll: (params: ScrollParams) => void = params => {
    this.props.onScroll(params)
    if (this.state.shouldScrollToSelected) {
      setTimeout(
        () =>
          this.setState({
            shouldScrollToSelected: false,
          }),
        0,
      )
    }
  }

  calculateRowHeight: (arg0: {index: number}) => number = ({index}) =>
    calculateRowHeight(index, this.props.items)

  onScrollbarPresenceChange: (arg0: {size: number; vertical: boolean}) => void = ({
    size,
    vertical,
  }) => {
    this.scrollBarWidth = vertical ? size : 0
  }

  handleMove: (arg0: MoveParams) => void = ({projectId, buildTypeId, shiftBy}) => {
    const {moveProject, moveBuildType} = this.props

    if (buildTypeId != null && moveBuildType != null) {
      moveBuildType(buildTypeId, shiftBy)
    } else if (projectId != null && moveProject != null) {
      moveProject(projectId, shiftBy)
    }
  }

  onRowsRendered: (arg0: {startIndex: number; stopIndex: number}) => void = ({
    startIndex,
    stopIndex,
  }) => {
    this.pageStartIndex = startIndex
    this.pageEndIndex = stopIndex
  }

  // noinspection JSCheckFunctionSignatures
  componentDidUpdate(prevProps: Props, prevState: State) {
    const {statuses, activeItem, items, searchQuery, searchActive, collapsed} = this.props
    const {selected, shouldFocusSelected} = this.state
    const prevSelectedItem = prevProps.items[prevState.selected]
    const selectedItem = items[selected]
    const list = this.list

    if (list != null) {
      if (
        selected !== prevState.selected &&
        selectedItem != null &&
        prevSelectedItem != null &&
        selectedItem.itemType === prevSelectedItem.itemType &&
        selectedItem.id === prevSelectedItem.id
      ) {
        const prevSelectedOffset = calculateRowOffset(prevState.selected, prevProps.items)
        const selectedOffset = calculateRowOffset(selected, items)
        const currentScrollOffset = list.getOffsetForRow({})
        const offset = currentScrollOffset + selectedOffset - prevSelectedOffset

        if (offset > TITLE_ITEM_HEIGHT) {
          list.scrollToPosition(offset)
        }
      }

      if (
        prevProps.statuses !== statuses ||
        prevProps.activeItem?.nodeType !== activeItem?.nodeType ||
        prevProps.activeItem?.id !== activeItem?.id ||
        prevProps.searchQuery !== searchQuery ||
        prevProps.items !== items
      ) {
        list.forceUpdateGrid()
      }

      if (
        (searchActive !== true && items.length !== prevProps.items.length) ||
        (searchActive === true && !prevProps.searchActive) ||
        items !== prevProps.items
      ) {
        list.recomputeRowHeights()
      }
    }

    if (collapsed && shouldFocusSelected) {
      this.setState({shouldFocusSelected: false})
    }
  }

  onWheel = () => {
    this.toggleTooltip(null)
  }

  toggleTooltip = (id: string | null) => {
    if (this.hoverTimeout) {
      window.clearTimeout(this.hoverTimeout)
      this.hoverTimeout = null
    }
    this.tree?.removeEventListener('wheel', this.onWheel)

    if (id == null) {
      this.setState({showTooltipFor: null})
      return
    }

    this.tree?.addEventListener('wheel', this.onWheel, {passive: true})
    this.hoverTimeout = window.setTimeout(() => {
      this.setState({showTooltipFor: id})
    }, TOOLTIP_TIMEOUT_MS)
  }

  moveSelectedItem(shiftBy: number) {
    const {selected} = this.state

    if (selected === -1) {
      return
    }

    const {items} = this.props
    const selectedItem = items[selected]

    if (selectedItem.group === 'favorites') {
      this.handleMove({...getIdProps(selectedItem), shiftBy})
    }
  }

  select(getIndex: (arg0: number) => number) {
    this.setState(({selected}) => ({
      selected: getIndex(selected),
      shouldFocusSelected: true,
      shouldScrollToSelected: true,
    }))
  }

  focusQueryIfSearchIsActive() {
    if (this.search != null && this.props.searchActive === true) {
      this.search.focus()
    }
  }

  render(): React.ReactNode {
    const {
      items,
      className,
      contentClassName,
      itemParentClassName,
      collapsed,
      activeItem,
      checkedItems,
      ready,
      allProjectsReady,
      children,
      placeholder,
    }: Props = this.props
    const {selected, shouldScrollToSelected}: State = this.state
    const rowCount = !ready || !allProjectsReady ? items.length + 1 : items.length
    const classes = classNames(styles.sidebar, className)
    const selectedItem = items[selected]
    const selectedItemId = selectedItem != null ? getProjectTreeItemId(selectedItem) : undefined
    return (
      <>
        <Shortcuts scope={this.shortcutsScope} map={this.shortcutsMap} />
        <div // It listens to keydown events from children
          role="presentation"
          className={classes}
          ref={this.sidebarRef}
          onKeyDown={this.onKeyDown}
        >
          {this.props.renderSearch({
            sidebarRef: this.sidebarRef,
            inputRef: this.setSearchRef,
            selectedItemId,
            collapsed,
            onEscape: this.focusList,
          })}
          {!ready && <SidebarSkeleton />}
          {ready && !collapsed && rowCount > 0 && (
            <div className={classNames(styles.content, contentClassName)}>
              <div // It listens to focus events from children
                role="presentation"
                ref={this.setTreeRef}
                className={classNames(styles.projectsTree, itemParentClassName)}
                onBlur={this.onTreeBlur}
                onFocus={this.onTreeFocus}
              >
                <Plugin placeId={PlaceId.SAKURA_SIDEBAR_TOP} />
                {items.length === 0 ? (
                  <SidebarSkeleton />
                ) : (
                  <ProjectsTreeList
                    aria-label="Projects"
                    tabIndex={-1}
                    containerProps={containerProps}
                    className={styles.list}
                    ref={this.setListRef}
                    rowCount={rowCount}
                    rowHeight={this.calculateRowHeight}
                    estimatedRowSize={REGULAR_ITEM_HEIGHT}
                    rowRenderer={this.rowRenderer}
                    onScrollbarPresenceChange={this.onScrollbarPresenceChange}
                    scrollToIndex={shouldScrollToSelected ? selected : undefined}
                    onScroll={this.onListScroll}
                    onRowsRendered={this.onRowsRendered} // we need to pass these props to trigger updates when they change
                    shouldScrollToSelected={shouldScrollToSelected}
                    selected={selected}
                    activeItem={activeItem}
                    checkedItems={checkedItems}
                    items={items}
                    showTooltipFor={this.state.showTooltipFor}
                  />
                )}
              </div>
            </div>
          )}
          {ready && rowCount === 0
            ? (placeholder ?? (
                <Suspense>
                  <ProjectsTreePlaceholder />
                </Suspense>
              ))
            : null}
          {children}
        </div>
      </>
    )
  }
}

export default ProjectsTree
