import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import Tag from '@jetbrains/ring-ui-built/components/tag/tag'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import {useContext, useMemo} from 'react'
import {useLinkClickHandler} from 'react-router'

import {useAppSelector} from '../../../hooks/react-redux'
import {useProjectId} from '../../../hooks/routes'
import useStatusSubscription from '../../../hooks/useStatusSubscription'
import {getIsReadOnly, getStatus} from '../../../selectors'
import {getProjectStatusRequest, ROOT_PROJECT_ID} from '../../../types'
import type {ProjectId, ProjectOrBuildTypeStatus} from '../../../types'
import {projectCreateHint} from '../../packages/Hints/HintItems/Hints.projectOverview'
import {useHint} from '../../packages/Hints/Hints.hooks'
import {
  isCreateProjectNewUiEnabled,
  isEarlyAccessLabelEnabled,
} from '../../pages/PipelinesPages/utils/featureToggles'
import {ProjectsTreeContext} from '../ProjectsTree/ProjectsTree.context'
import {useSequenceLoaderReadyHandler} from '../SequenceLoader/SequenceLoader.hooks'

import styles from './CreateEntityButton.module.css'

import {getCreateBuildTypeHref, getCreatePipelineHref, getCreateProjectHref} from 'src/routes'
import {truthy} from 'src/utils/guards'

type CreateEntityOptions = {
  createProject?: boolean
  createBuildType?: boolean
  createPipeline?: boolean
}
export function useCreateEntityMenu(
  parentProjectId?: ProjectId,
  {
    createProject = true,
    createPipeline = true,
    createBuildType = true,
  }: CreateEntityOptions | undefined = {},
) {
  const isParentRoot = parentProjectId === ROOT_PROJECT_ID
  const isReadOnly = useAppSelector(state => getIsReadOnly(state, parentProjectId))
  const {isAdmin} = useContext(ProjectsTreeContext)

  const canRenderSection =
    !isReadOnly && parentProjectId != null && (createProject || createBuildType || createPipeline)

  const createProjectHref = parentProjectId && getCreateProjectHref(parentProjectId)
  const createProjectLinkClickHandler = useLinkClickHandler(createProjectHref ?? '')
  const createBuildTypeHref = parentProjectId && getCreateBuildTypeHref(parentProjectId)
  const createPipelineHref = parentProjectId && getCreatePipelineHref(parentProjectId)
  const createPipelineLinkClickHandler = useLinkClickHandler(createPipelineHref ?? '')

  return useMemo(() => {
    if (!canRenderSection) {
      return []
    }

    const maybeItems: Array<ListDataItem | false> = [
      createBuildType &&
        !isParentRoot && {
          key: 'new-build-configuration',
          href: createBuildTypeHref,
          label: (
            <>
              <SvgIcon className={styles.icon} icon="buildType" />
              {'New build configuration'}
            </>
          ),
          onClick: (_, e) => {
            e.stopPropagation()
          },
        },
      createPipeline &&
        !isParentRoot && {
          key: 'new-pipeline',
          href: createPipelineHref,
          label: (
            <>
              <SvgIcon className={styles.icon} icon="pipeline" />
              {'New pipeline'}
              {isEarlyAccessLabelEnabled && (
                <Tag
                  readOnly
                  textColor={'var(--ring-success-color)'}
                  backgroundColor={'var(--ring-added-background-color)'}
                  className={styles.earlyAccessTag}
                >
                  {'Early access'}
                </Tag>
              )}
            </>
          ),
          onClick: (_, e) => {
            if (isAdmin) {
              e.stopPropagation()
            } else {
              createPipelineLinkClickHandler(e as React.MouseEvent<HTMLAnchorElement>)
            }
          },
        },
      createProject && {
        key: 'new-project',
        href: createProjectHref,
        label: (
          <>
            <SvgIcon className={styles.icon} icon="project" />
            {isParentRoot ? 'New project' : 'New subproject'}
          </>
        ),
        onClick: (_, e) => {
          if (isAdmin || !isCreateProjectNewUiEnabled) {
            e.stopPropagation()
          } else {
            createProjectLinkClickHandler(e as React.MouseEvent<HTMLAnchorElement>)
          }
        },
      },
    ]
    return maybeItems.filter(truthy)
  }, [
    canRenderSection,
    createBuildType,
    isParentRoot,
    createBuildTypeHref,
    createPipeline,
    createPipelineHref,
    createProject,
    createProjectHref,
    isAdmin,
    createPipelineLinkClickHandler,
    createProjectLinkClickHandler,
  ])
}

export function useCreateEntityButton() {
  const projectId = useProjectId()
  const statusRequest = getProjectStatusRequest(projectId)

  useStatusSubscription({projectId})
  const projectPermissions = useAppSelector(state => {
    const statusObj: ProjectOrBuildTypeStatus | null | undefined = getStatus(state, statusRequest)
    return statusObj != null && 'projectPermissions' in statusObj
      ? statusObj.projectPermissions
      : null
  })

  const {canCreateSubProject, canEditProject, canCreatePipelines} = projectPermissions ?? {}
  const actions = useCreateEntityMenu(projectId, {
    createProject: canCreateSubProject,
    createBuildType: canEditProject,
    createPipeline: canCreatePipelines,
  })

  useHint(actions.length > 0 ? projectCreateHint : null)
  useSequenceLoaderReadyHandler(true)

  return actions
}
