import classNames from 'classnames'
import {memo, useState} from 'react'

import type {ProjectId} from '../../../../../types'
import {sidebarSettings} from '../../../../App/SidebarPanel/SidebarPanel.slices'
import CreateEntityButton from '../../../CreateEntityButton/CreateEntityButton'
import {useCreateEntityMenu} from '../../../CreateEntityButton/CreateEntityButton.hooks'
import styles from '../ProjectsTreeItem.module.css'

import {useAppDispatch} from 'src/hooks/react-redux'

type Props = {
  projectId?: ProjectId
  canCreateSubProject?: boolean
  canEditProject?: boolean
  canCreatePipelines?: boolean
}

function ProjectsTreeItemCreateButton({
  projectId,
  canEditProject,
  canCreateSubProject,
  canCreatePipelines,
}: Props) {
  const dispatch = useAppDispatch()
  const [isMenuShown, setIsMenuShown] = useState(false)
  const actions = useCreateEntityMenu(projectId, {
    createProject: Boolean(canCreateSubProject),
    createBuildType: Boolean(canEditProject),
    createPipeline: Boolean(canCreatePipelines),
  })

  return (
    <CreateEntityButton
      actions={actions}
      className={classNames(styles.createButton, {[styles.activeCreateButton]: isMenuShown})}
      onMenuShow={() => {
        setIsMenuShown(true)
        dispatch(sidebarSettings.actions.setAutoCollapseDisabled(true))
      }}
      onMenuHide={() => {
        setIsMenuShown(false)
        dispatch(sidebarSettings.actions.setAutoCollapseDisabled(false))
      }}
      data-create-entity-button
    />
  )
}

export default memo(ProjectsTreeItemCreateButton)
