import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {ControlsHeightContext} from '@jetbrains/ring-ui-built/components/global/controls-height'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/list'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import PopupMenu from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import type {MouseEvent} from 'react'
import {useCallback, useContext, useId} from 'react'

export type Props = {
  actions: ListDataItem[]
  className?: string
  withBorder?: boolean
  onClick?: (e: MouseEvent<HTMLButtonElement>) => void
  onMenuShow?: () => void
  onMenuHide?: () => void
}
function CreateEntityButton({actions, onMenuShow, onMenuHide, ...restProps}: Props) {
  const id = useId()
  const controlsHeight = useContext(ControlsHeightContext)

  const handleClick = useCallback((event: React.SyntheticEvent) => {
    event.preventDefault()
    event.stopPropagation()
  }, [])

  return (
    actions.length > 0 && (
      <span role="presentation" onClick={handleClick}>
        <Dropdown
          anchor={({active}) => {
            const button = (
              <IconButton height={controlsHeight} {...restProps} aria-labelledby={id} icon="add" />
            )
            return active ? (
              button
            ) : (
              <Tooltip
                id={id}
                delay={100}
                title="Create"
                popupProps={{offset: 6, directions: [Directions.BOTTOM_LEFT]}}
              >
                {button}
              </Tooltip>
            )
          }}
          onShow={onMenuShow}
          onHide={onMenuHide}
        >
          <PopupMenu offset={4} trapFocus shortcuts data={actions} closeOnSelect />
        </Dropdown>
      </span>
    )
  )
}

export default CreateEntityButton
